package multipartsio

import (
	"io"
	"mime/multipart"
)

// PartsReader wraps a single file generated by multipart.Form and copy all of
// them into a single writer. This implements io.WriterTo/io.Reader interface so
// it can be used in io.Copy
type PartsReader struct {
	part *multipart.FileHeader
	fh   multipart.File
}

func NewPartsReader(part *multipart.FileHeader) *PartsReader {
	return &PartsReader{part: part}
}

// WriteTo write the part to the destination.
func (pr *PartsReader) WriteTo(w io.Writer) (int64, error) {
	f, err := pr.part.Open()
	if err != nil {
		return 0, err
	}
	defer f.Close()
	return io.Copy(w, f)
}

// Read reads data from parts sequentially. User should use the WriteTo methods
// instead.
func (pr *PartsReader) Read(p []byte) (int, error) {
	// if we have a cached file handler, use it
	if pr.fh != nil {
		n, err := pr.fh.Read(p)
		// if there's error, close and reset the cached file handler.
		// if the error is EOF, then treat it as noop and advance the pointer
		// to next file
		if err != nil {
			pr.fh.Close()
			pr.fh = nil
		}
		return n, err
	}
	fh, err := pr.part.Open()
	if err != nil {
		return 0, err
	}
	// cached the file handler for next use
	pr.fh = fh
	return pr.fh.Read(p)
}
